-- ---------------------------------------------------------------- Índices (no respaldan constraints)
CREATE INDEX auditoria_cliente_id_idx ON public.auditoria USING btree (cliente_id);
CREATE INDEX auditoria_organizacion_id_idx ON public.auditoria USING btree (organizacion_id);
CREATE INDEX pos_abonos_cli_idx ON public.pos_abonos USING btree (cliente_id);
CREATE INDEX idx_pos_acceso_org ON public.pos_acceso USING btree (organizacion_id);
CREATE INDEX idx_pos_alm_org ON public.pos_almacenes USING btree (organizacion_id);
CREATE INDEX pos_apartados_cliente_idx ON public.pos_apartados USING btree (organizacion_id, cliente_id, estado);
CREATE UNIQUE INDEX pos_apartados_serial_activo_uidx ON public.pos_apartados USING btree (organizacion_id, serial_id) WHERE ((serial_id IS NOT NULL) AND (estado <> ALL (ARRAY['cancelado'::text, 'entregado'::text, 'vencido'::text])));
CREATE INDEX idx_pos_aslin_asiento ON public.pos_asiento_lineas USING btree (asiento_id);
CREATE INDEX idx_pos_asientos_org ON public.pos_asientos USING btree (organizacion_id);
CREATE UNIQUE INDEX pos_asientos_fin_pago_origen_uidx ON public.pos_asientos USING btree (organizacion_id, tipo, origen_id) WHERE ((origen_id IS NOT NULL) AND (tipo = ANY (ARRAY['pago_cuota'::text, 'reversa_pago_cuota'::text])));
CREATE UNIQUE INDEX pos_asientos_pos_origen_uidx ON public.pos_asientos USING btree (organizacion_id, tipo, origen_id) WHERE ((origen_id IS NOT NULL) AND (tipo = ANY (ARRAY['venta'::text, 'compra'::text])));
CREATE UNIQUE INDEX pos_banco_conc_ext_uidx ON public.pos_banco_conciliaciones USING btree (extracto_id);
CREATE UNIQUE INDEX pos_banco_conc_mov_uidx ON public.pos_banco_conciliaciones USING btree (movimiento_id);
CREATE INDEX pos_banco_conc_org_idx ON public.pos_banco_conciliaciones USING btree (organizacion_id, cuenta_bancaria_id);
CREATE UNIQUE INDEX pos_banco_extracto_fp_uidx ON public.pos_banco_extractos USING btree (organizacion_id, cuenta_bancaria_id, fingerprint);
CREATE INDEX pos_banco_extracto_org_fecha_idx ON public.pos_banco_extractos USING btree (organizacion_id, cuenta_bancaria_id, fecha DESC);
CREATE INDEX pos_banco_mov_org_fecha_idx ON public.pos_banco_movimientos USING btree (organizacion_id, cuenta_bancaria_id, fecha DESC);
CREATE UNIQUE INDEX pos_banco_mov_origen_clave_uidx ON public.pos_banco_movimientos USING btree (organizacion_id, origen_clave) WHERE (origen_clave IS NOT NULL);
CREATE INDEX pos_caja_mov_idx ON public.pos_caja_movimientos USING btree (caja_id);
CREATE UNIQUE INDEX pos_cajas_una_abierta_por_usuario_uidx ON public.pos_cajas USING btree (organizacion_id, usuario_id) WHERE ((estado = 'abierta'::text) AND (usuario_id IS NOT NULL));
CREATE INDEX pos_cajas_usuario_fecha_idx ON public.pos_cajas USING btree (organizacion_id, usuario_id, apertura DESC);
CREATE INDEX pos_compra_items_idx ON public.pos_compra_items USING btree (compra_id);
CREATE INDEX pos_compra_pagos_prov_idx ON public.pos_compra_pagos USING btree (proveedor_id);
CREATE UNIQUE INDEX pos_compras_org_operacion_uidx ON public.pos_compras USING btree (organizacion_id, operacion_id) WHERE (operacion_id IS NOT NULL);
CREATE INDEX pos_compras_prov_idx ON public.pos_compras USING btree (proveedor_id);
CREATE INDEX idx_pos_cotiz_items_cot ON public.pos_cotizacion_items USING btree (cotizacion_id);
CREATE INDEX idx_pos_cotiz_org ON public.pos_cotizaciones USING btree (organizacion_id);
CREATE INDEX pos_credito_eventos_fin_idx ON public.pos_credito_eventos USING btree (financiamiento_id, created_at DESC);
