CREATE INDEX idx_pos_invmov_org ON public.pos_inv_movimientos USING btree (organizacion_id);
CREATE INDEX idx_pos_invmov_prod ON public.pos_inv_movimientos USING btree (producto_id);
CREATE INDEX idx_pos_ncf_org ON public.pos_ncf_secuencias USING btree (organizacion_id);
